function problem(op,level,n){let a,b,answer,remainder=0,symbol="+";const p=Math.min(4,Math.ceil(n/3));if(op==="decimal"){let minus=p>2;a=rnd(level==="support"?110:120,level==="expert"?9999:4999);b=rnd(10,Math.max(11,Math.min(a-1,3499)));if(minus&&b>a)[a,b]=[b,a];return{op,symbol:minus?"−":"+",a,b,answer:minus?a-b:a+b,displayA:decimal(a),displayB:decimal(b),displayAnswer:decimal(minus?a-b:a+b)}}if(op==="add"){a=rnd(20,level==="expert"?4999:499);b=rnd(8,level==="expert"?3999:399);answer=a+b}else if(op==="sub"){a=rnd(level==="support"?30:120,level==="expert"?9999:999);b=rnd(10,a-1);answer=a-b;symbol="−"}else if(op==="mul"){a=rnd(12,level==="expert"?999:299);b=rnd(2,level==="support"?9:level==="expert"?99:29);answer=a*b;symbol="×"}else{b=rnd(2,level==="expert"?35:12);answer=rnd(2,level==="expert"?250:99);if(level!=="support"&&p===4)remainder=rnd(1,b-1);a=b*answer+remainder;symbol="÷"}return{op,a,b,answer,remainder,symbol}}

