function Canvas({reset}){const c=useRef(),box=useRef(),down=useRef(false),last=useRef(),hist=useRef([]);const[tool,setTool]=useState("pen"),[undoable,setUndoable]=useState(false);const white=()=>{let x=c.current?.getContext("2d");if(x){x.fillStyle="white";x.fillRect(0,0,c.current.width,c.current.height)}};useEffect(()=>{const resize=()=>{let el=c.current,r=box.current?.getBoundingClientRect();if(!el||!r)return;let snap=el.width?el.toDataURL():null,d=devicePixelRatio||1;el.width=Math.max(240,r.width)*d;el.height=(innerWidth<640?220:330)*d;el.style.width="100%";el.style.height=innerWidth<640?"220px":"330px";white();if(snap){let i=new Image;i.onload=()=>el.getContext("2d").drawImage(i,0,0,el.width,el.height);i.src=snap}};resize();let ro=new ResizeObserver(resize);ro.observe(box.current);return()=>ro.disconnect()},[]);useEffect(()=>{white();hist.current=[];setUndoable(false)},[reset]);const pos=e=>{let r=c.current.getBoundingClientRect();return{x:(e.clientX-r.left)*c.current.width/r.width,y:(e.clientY-r.top)*c.current.height/r.height}};const start=e=>{e.preventDefault();e.currentTarget.setPointerCapture?.(e.pointerId);hist.current.push(c.current.toDataURL());setUndoable(true);down.current=true;last.current=pos(e)};const move=e=>{if(!down.current)return;e.preventDefault();let x=c.current.getContext("2d"),p=pos(e),d=devicePixelRatio||1;x.beginPath();x.moveTo(last.current.x,last.current.y);x.lineTo(p.x,p.y);x.lineCap="round";x.strokeStyle=tool==="pen"?"#172033":"white";x.lineWidth=(tool==="pen"?4:28)*d;x.stroke();last.current=p};const stop=e=>{down.current=false;if(e.currentTarget.hasPointerCapture?.(e.pointerId))e.currentTarget.releasePointerCapture(e.pointerId)};const clear=()=>{white();hist.current=[];setUndoable(false)};const undo=()=>{let s=hist.current.pop();if(!s)return;let i=new Image;i.onload=()=>{white();c.current.getContext("2d").drawImage(i,0,0,c.current.width,c.current.height)};i.src=s;setUndoable(hist.current.length>0)};return <div className="canvas-card"><div className="canvas-tools"><span><Button onClick={()=>setTool("pen")} className={tool==="pen"?"active":""}><Pencil/>Penna</Button><Button onClick={()=>setTool("eraser")} className={tool==="eraser"?"active":""}><Eraser/>Sudd</Button></span><span><Button disabled={!undoable} onClick={undo}><Undo2/></Button><Button onClick={clear}><Trash2/></Button></span></div><div ref={box} className="canvas-wrap"><canvas ref={c} onPointerDown={start} onPointerMove={move} onPointerUp={stop} onPointerCancel={stop}/></div></div>}
function Profiles({profiles,setProfiles,setActive,setScreen}){
  const[name,setName]=useState(""),[hero,setHero]=useState("nova");
  const create=()=>{let n=name.trim().slice(0,20);if(!n)return;let id=`p-${Date.now()}`;setProfiles(x=>[...x,{id,name:n,heroId:hero,heroCustomization:{...defaultCustomization,color:HERO_COLORS[HEROES.findIndex(h=>h.id===hero)%HERO_COLORS.length].id},stats:migrateStats({})}]);setActive(id);setScreen("workshop")};
  return <main className="start"><h1>🏰 Matematikmästarna</h1><div className="panel profile-panel"><h2>{profiles.length?"Välj elevprofil":"Skapa elevprofil"}</h2>{profiles.length>0&&<div className="profile-list">{profiles.map(p=>{let h=HEROES.find(hero=>hero.id===p.heroId)||HEROES[0];return <div className="profile-card" key={p.id}><HeroAvatar heroId={p.heroId} customization={p.heroCustomization}/><div><b>{p.name}</b><span>{h.name} · {p.stats.xp} XP</span></div><Button className="primary" onClick={()=>{setActive(p.id);setScreen("home")}}>Spela</Button><Button onClick={()=>{setActive(p.id);setScreen("workshop")}}>🎨 Anpassa</Button><Button className="delete-profile" onClick={()=>setProfiles(x=>x.filter(y=>y.id!==p.id))}><Trash2/></Button></div>})}</div>}<h2>Ny profil</h2><input value={name} onChange={e=>setName(e.target.value)} placeholder="Elevens namn"/><div className="hero-choice-grid">{HEROES.map(h=><button key={h.id} className={`hero-choice ${hero===h.id?"selected":""}`} onClick={()=>setHero(h.id)}><HeroAvatar heroId={h.id} customization={{...defaultCustomization,color:HERO_COLORS[HEROES.indexOf(h)].id}} size="large"/><b>{h.name}</b><span>{h.role}</span>{hero===h.id&&<em>✓ Vald hjälte</em>}</button>)}</div><Button className="primary wide" onClick={create}>Skapa profil och anpassa <ChevronRight/></Button></div></main>
}
function HeroWorkshop({profile,save,back}){
  const[heroId,setHeroId]=useState(profile.heroId||"nova"),[custom,setCustom]=useState({...defaultCustomization,...profile.heroCustomization});
  const categories=[{key:"color",title:"Färgtema",choices:HERO_COLORS},{key:"hat",title:"Huvudbonad",choices:HERO_HATS},{key:"item",title:"Utrustning",choices:HERO_ITEMS},{key:"companion",title:"Följeslagare",choices:HERO_COMPANIONS}];
  return <main className="workshop"><Button onClick={back}><ArrowLeft/>Tillbaka</Button><div className="workshop-head"><div><small>HJÄLTEVERKSTADEN</small><h1>Anpassa {profile.name}s hjälte</h1><p>Valen ändrar bara utseendet och ger inga matematiska fördelar.</p></div><HeroAvatar heroId={heroId} customization={custom} size="xl"/></div><section className="workshop-section"><h2>1. Välj hjälte</h2><div className="workshop-grid heroes-five">{HEROES.map(hero=><button key={hero.id} className={heroId===hero.id?"selected":""} onClick={()=>setHeroId(hero.id)}><HeroAvatar heroId={hero.id} customization={custom}/><b>{hero.name}</b><span>{hero.role}</span></button>)}</div></section>{categories.map((category,index)=><section className="workshop-section" key={category.key}><h2>{index+2}. {category.title}</h2><div className="workshop-grid">{category.choices.map(choice=><button key={choice.id} className={custom[category.key]===choice.id?"selected":""} onClick={()=>setCustom(value=>({...value,[category.key]:choice.id}))}>{category.key==="color"?<i className="color-dot" style={{background:choice.value}}/>:<span className="choice-icon">{choice.icon}</span>}<b>{choice.name}</b></button>)}</div></section>)}<div className="workshop-save"><Button className="primary" onClick={()=>save(heroId,custom)}>Spara hjälte <Check/></Button></div></main>
}
function App(){
  const[profiles,setProfiles]=useState([]),[active,setActive]=useState(null),[screen,setScreen]=useState("profiles"),[world,setWorld]=useState(1),[level,setLevel]=useState("base"),[masterLevel,setMasterLevel]=useState(0),[puzzleTrack,setPuzzleTrack]=useState("support"),[weeklyMission,setWeeklyMission]=useState(null);
  useEffect(()=>{try{let loaded=migrateProfiles(JSON.parse(localStorage.getItem(STORAGE)||"[]"));setProfiles(loaded);setActive(localStorage.getItem(ACTIVE))}catch{setProfiles([])}},[]);
  useEffect(()=>{localStorage.setItem(STORAGE,JSON.stringify(profiles));active?localStorage.setItem(ACTIVE,active):localStorage.removeItem(ACTIVE)},[profiles,active]);
  let profile=profiles.find(p=>p.id===active);
  const stats=fn=>setProfiles(ps=>ps.map(p=>p.id===active?{...p,stats:migrateStats(fn(migrateStats(p.stats)))}:p));
  if(screen==="profiles"||!profile)return <Profiles {...{profiles,setProfiles,setActive,setScreen}}/>;
  const saveHero=(heroId,heroCustomization)=>{setProfiles(ps=>ps.map(p=>p.id===active?{...p,heroId,heroCustomization}:p));setScreen("home")};
  return <><header><Button onClick={()=>setScreen("home")}><HeroAvatar heroId={profile.heroId} customization={profile.heroCustomization} size="small"/>{profile.name}</Button><span><Heart/> {profile.stats.lives} <Zap/> {profile.stats.streak} <Star/> {profile.stats.xp}</span><div className="header-actions"><Button onClick={()=>setScreen("workshop")}>🎨 Hjälte</Button><Button onClick={()=>setScreen("profiles")}><UserRoundPen/>Byt spelare</Button></div></header>
  {screen==="home"&&<HomeScreen profile={profile} adventure={()=>setScreen("map")} master={()=>setScreen("mastermap")} training={()=>setScreen("training")} weekly={()=>setScreen("weekly")}/>} 
  {screen==="workshop"&&<HeroWorkshop profile={profile} save={saveHero} back={()=>setScreen("home")}/>} 
  {screen==="training"&&<ComingSoon icon="⚡" title="Träningsarenan" text="Tabeller, talfakta och huvudräkning är på väg." back={()=>setScreen("home")}/>} 
  {screen==="weekly"&&<WeeklyHub profile={profile} back={()=>setScreen("home")} start={()=>{setWeeklyMission(WEEK40);setScreen("weeklygame")}}/>}
  {screen==="weeklygame"&&<WeeklyMission key={`${active}-${weeklyMission?.id}`} mission={weeklyMission||WEEK40} profile={profile} stats={stats} back={()=>setScreen("weekly")}/>} 
  {screen==="map"&&<MapScreen profile={profile} open={id=>{setWorld(id);setScreen("level")}} openPuzzles={()=>setScreen("puzzlemap")} back={()=>setScreen("home")}/>}
  {screen==="puzzlemap"&&<PuzzleMap profile={profile} back={()=>setScreen("map")} start={track=>{setPuzzleTrack(track);setScreen("puzzlegame")}}/>}
  {screen==="puzzlegame"&&<PuzzleGame key={`${active}-puzzle-${puzzleTrack}`} profile={profile} track={puzzleTrack} stats={stats} back={()=>setScreen("puzzlemap")}/>} 
  {screen==="mastermap"&&<MasterMap profile={profile} back={()=>setScreen("home")} play={i=>{setMasterLevel(i);setScreen("mastergame")}}/>} 
  {screen==="mastergame"&&<MasterGame key={`${active}-master-${masterLevel}`} profile={profile} index={masterLevel} stats={stats} back={()=>setScreen("mastermap")} nextLevel={()=>{setMasterLevel(i=>Math.min(19,i+1));setScreen("mastergame")}}/>} 
  {screen==="level"&&<Level world={world} back={()=>setScreen("map")} pick={l=>{setLevel(l);stats(st=>({...st,lives:5,streak:0}));setScreen("game")}}/>} 
  {screen==="game"&&<Game key={`${active}-${world}-${level}`} profile={profile} world={world} level={level} stats={stats} exit={()=>setScreen("level")} map={()=>setScreen("map")}/>}</>}

function HomeScreen({profile,adventure,master,training,weekly}){let masterStats=profile.stats.talriket||{},missions=profile.stats.weeklyMissions||{};return <main className="home-screen"><div className="home-welcome"><HeroAvatar heroId={profile.heroId} customization={profile.heroCustomization} size="large"/><div><small>VÄLKOMMEN TILLBAKA</small><h1>{profile.name}</h1><p>Välj hur du vill träna matematik idag.</p></div><strong>{profile.stats.xp} XP</strong></div><div className="home-grid"><button className="home-card adventure-card" onClick={adventure}><span>🏰</span><div><small>MATEMATIKVÄRLDAR</small><h2>Äventyr</h2><p>Utforska uppställning, decimaler och fler matematikområden.</p><b>Öppna äventyrskartan <ChevronRight/></b></div></button><button className="home-card master-card" onClick={master}><span>🏹</span><div><small>STRATEGI OCH RESONEMANG</small><h2>Mästarjakten</h2><p>Bygg tal. Hitta flera vägar. Besegra bossarna.</p><em>{masterStats.totalStars||0}/60 stjärnor</em><b>Fortsätt jakten <ChevronRight/></b></div></button><button className="home-card training-card" onClick={training}><span>⚡</span><div><small>AUTOMATISERING</small><h2>Träningsarenan</h2><p>Tabeller, talfakta och huvudräkning i korta pass.</p><em className="soon-badge">Kommer snart</em><b>Visa arenan <ChevronRight/></b></div></button><button className="home-card weekly-card" onClick={weekly}><span>📜</span><div><small>KLASSENS AKTUELLA TRÄNING</small><h2>Veckans uppdrag</h2><p>Vecka 40: Nollornas kraft</p><em>{missions[WEEK40.id]?.status==="completed"?"✅ Genomfört":"8 uppgifter · 10–15 min"}</em><b>Öppna uppdraget <ChevronRight/></b></div></button></div></main>}

function ComingSoon({icon,title,text,back}){return <main className="coming-page"><Button onClick={back}><ArrowLeft/>Startsidan</Button><div className="coming-panel"><span>{icon}</span><small>UNDER UTVECKLING</small><h1>{title}</h1><p>{text}</p><strong>Kommer snart</strong></div></main>}

