const SKILL_NAMES={"multiply-place-value":"multiplikation med tiotal och hundratal","decimal-multiplication":"decimalmultiplikation","simplify-division":"att förenkla division","decimal-division":"decimaldivision","unknown-factor":"att bestämma ett okänt tal","compare-expressions":"att jämföra uttryck","unit-price":"pris per styck","proportional-distance":"sträcka och proportionalitet"};
const cleanAnswer=v=>String(v).trim().replace(/\s/g,"").replace(".",",");
function WeeklyHub({profile,back,start}){let missions=profile.stats.weeklyMissions||{},r=missions[WEEK40.id];return <main className="weekly-hub"><style>{WEEKLY_CSS}</style><Button onClick={back}><ArrowLeft/>Startsidan</Button><div className="weekly-head"><span>📜</span><div><small>VECKANS UPPDRAG</small><h1>Uppdrag och historik</h1><p>Korta uppdrag som följer det klassen arbetar med.</p></div></div><section className="weekly-active"><div><small>AKTUELLT · VECKA 40</small><h2>Nollornas kraft</h2><p>Multiplikation och division med stora tal och decimaltal.</p><span>8 uppgifter · cirka 10–15 minuter</span></div><Button className="primary" onClick={start}>{r?.status==="completed"?"Träna igen":r?.status==="in-progress"?"Fortsätt":"Starta uppdraget"}<ChevronRight/></Button></section><div className="weekly-columns"><section><h2>Tidigare uppdrag</h2>{r?.status==="completed"?<div className="mission-row"><div><b>✅ Vecka 40 · Nollornas kraft</b><span>Bäst {r.bestCorrect||r.correct}/8 · {r.attempts||1} försök</span></div><Button onClick={start}>Öppna</Button></div>:<div className="empty-missions"><span>🗂️</span><p>Genomförda uppdrag visas här när en ny vecka börjar.</p></div>}</section><section className="exam-card"><span>📝</span><small>PERSONLIG REPETITION</small><h2>Träna inför prov</h2><p>Personliga övningar och repetition inför kommande prov.</p><strong>Kommer snart</strong></section></div></main>}
function Confidence({onChoose}){return <div className="confidence-card"><h2>Hur säker känner du dig?</h2><p>Det finns inget rätt eller fel svar.</p><div>{["Inte säker","Ganska säker","Mycket säker"].map(x=><button key={x} onClick={()=>onChoose(x)}>{x}</button>)}</div></div>}
function WeeklyMission({mission,profile,stats,back}){let saved=profile.stats.weeklyMissions?.[mission.id],[index,setIndex]=useState(saved?.status==="in-progress"?saved.index||0:0),[value,setValue]=useState(""),[tries,setTries]=useState(0),[records,setRecords]=useState([]),[feedback,setFeedback]=useState(null),[checkMode,setCheckMode]=useState(false),[confidence,setConfidence]=useState(saved?.confidence||[]),[askConfidence,setAskConfidence]=useState(false),[done,setDone]=useState(false),[canvasReset,setCanvasReset]=useState(0);let q=mission.questions[index],target=checkMode?q.check:q;const isCorrect=()=>target.answers.map(cleanAnswer).includes(cleanAnswer(value));const classify=()=>q.errors?.[cleanAnswer(value)]||(!value?"no-answer":tries?"persistent-error":"calculation-error");const submit=()=>{if(!value)return;let ok=isCorrect();if(checkMode){setRecords(r=>[...r,{skill:q.skill,ok,afterSupport:true,error:ok?null:classify()}]);setFeedback({ok,text:ok?"Du klarade en liknande uppgift efter stödet.":`Rätt svar är ${target.label}. Den här idén läggs i Matematikminnet.` ,advance:true});return}if(ok){setRecords(r=>[...r,{skill:q.skill,ok:true,independent:tries===0,withHint:tries>0}]);setFeedback({ok:true,text:q.explain,advance:true})}else if(tries<2){let n=tries+1;setTries(n);setFeedback({ok:false,text:q.hints[n-1],retry:true})}else{let error=classify();setRecords(r=>[...r,{skill:q.skill,ok:false,error,support:true}]);setFeedback({ok:false,text:`Rätt svar är ${q.answerLabel}. ${q.explain}`,showCheck:true})}};const proceed=()=>{if(feedback?.retry){setFeedback(null);setValue("");return}if(feedback?.showCheck){setCheckMode(true);setFeedback(null);setValue("");return}if(q.self&&!checkMode&&confidence.length<(index===3?1:2)){setFeedback(null);setAskConfidence(true);return}advance()};const advance=()=>{if(index===mission.questions.length-1){setDone(true);return}let ni=index+1;setIndex(ni);setValue("");setTries(0);setFeedback(null);setCheckMode(false);setCanvasReset(x=>x+1);stats(s=>({...s,weeklyMissions:{...s.weeklyMissions,[mission.id]:{...(s.weeklyMissions?.[mission.id]||{}),title:mission.title,status:"in-progress",index:ni,confidence}}}))};const chooseConfidence=x=>{let c=[...confidence,{after:index+1,value:x}];setConfidence(c);setAskConfidence(false);if(index===mission.questions.length-1)setDone(true);else advance()};useEffect(()=>{if(!done)return;let correctSkills=records.filter(r=>r.ok),errors=records.filter(r=>r.error),skillMap={...profile.stats.learningProfile?.skills},errorMap={...profile.stats.learningProfile?.errorTypes};mission.questions.forEach(item=>{let rr=records.filter(r=>r.skill===item.skill),ok=rr.some(r=>r.ok),ind=rr.some(r=>r.independent),after=rr.some(r=>r.afterSupport&&r.ok),old=skillMap[item.skill]||{attempts:0,independentSuccesses:0,supportSuccesses:0};skillMap[item.skill]={...old,attempts:(old.attempts||0)+1,independentSuccesses:(old.independentSuccesses||0)+(ind?1:0),supportSuccesses:(old.supportSuccesses||0)+(after?1:0),status:ind?"säker självständigt":after?"säker efter stöd":ok?"under utveckling":"behöver återkomma",lastSeen:new Date().toISOString()}});errors.forEach(r=>errorMap[r.error]=(errorMap[r.error]||0)+1);let review=Object.entries(skillMap).filter(([,v])=>v.status!=="säker självständigt").map(([skill])=>({skill,reviewAfterSessions:2}));let old=profile.stats.weeklyMissions?.[mission.id]||{},score=new Set(correctSkills.map(r=>r.skill)).size;stats(s=>({...s,xp:s.xp+score*6,weeklyMissions:{...s.weeklyMissions,[mission.id]:{title:mission.title,status:"completed",correct:score,bestCorrect:Math.max(old.bestCorrect||0,score),attempts:(old.attempts||0)+1,confidence,completedAt:new Date().toISOString()}},learningProfile:{skills:skillMap,errorTypes:errorMap,reviewQueue:review}}))},[done]);if(done){let good=[...new Set(records.filter(r=>r.ok).map(r=>r.skill))],needs=[...new Set(records.filter(r=>!r.ok||r.afterSupport).map(r=>r.skill))],after=records.filter(r=>r.afterSupport&&r.ok).map(r=>r.skill);return <main className="weekly-result"><style>{WEEKLY_CSS}</style><div className="weekly-result-card"><span>📜</span><small>VECKA 40 GENOMFÖRD</small><h1>Nollornas kraft</h1><section><h2>🌟 Det här kan du</h2><p>{good.length?`I det här uppdraget visade du förståelse för ${good.slice(0,3).map(x=>SKILL_NAMES[x]).join(", ")}.`:"Du arbetade vidare även när uppgifterna var utmanande."}</p></section><section><h2>🌱 Det här håller du på att lära dig</h2><p>{after.length?`Efter stöd klarade du en ny uppgift om ${after.slice(0,2).map(x=>SKILL_NAMES[x]).join(" och ")}.`:needs.length?`Du håller på att utveckla ${needs.slice(0,2).map(x=>SKILL_NAMES[x]).join(" och ")}.`:"Du visade säkerhet i alla delar."}</p></section><section><h2>🎯 Ditt nästa steg</h2><p>{needs.length?`Träna vidare på ${needs.slice(0,3).map(x=>SKILL_NAMES[x]).join(", ")}. Uppgifterna återkommer senare.`:"Prova att förklara varför strategierna fungerar för någon annan."}</p></section><section><h2>💡 Kom ihåg</h2><p>Uppskatta först. Då upptäcker du lättare om decimaltecknet eller nollorna har hamnat fel.</p></section><section><h2>🔁 Matematikminnet</h2><p>{needs.length?"Spelet har sparat dina träningsbehov lokalt och lägger dem i repetitionskön.":"Spelet har sparat vilka områden du klarade självständigt."}</p></section><div className="confidence-summary"><b>Din självskattning:</b> {confidence.map(c=>c.value).join(" → ")||"Inte besvarad"}</div><Button className="primary" onClick={back}>Till uppdragen</Button></div></main>}if(askConfidence)return <main className="weekly-game"><style>{WEEKLY_CSS}</style><Confidence onChoose={chooseConfidence}/></main>;return <main className="weekly-game"><style>{WEEKLY_CSS}</style><Button onClick={back}><ArrowLeft/>Uppdragen</Button><div className="weekly-game-top"><span>📜 Vecka 40 · Nollornas kraft</span><b>{checkMode?"Kontrolluppgift":`Uppgift ${index+1} av 8`}</b></div><div className="progress"><i style={{width:`${(index+(checkMode?.5:0))/8*100}%`}}/></div><div className="weekly-workspace"><section><h2><Brush/> Skrivyta</h2><Canvas reset={canvasReset}/><p className="weekly-canvas-note">Skrivytan är till för dina uträkningar. Spelet bedömer svaret du skriver i svarsrutan.</p></section><article className="weekly-question"><small>{checkMode?"VISA VAD DU LÄRT DIG":SKILL_NAMES[q.skill].toUpperCase()}</small><h1>{target.prompt}</h1>{(target.type||q.type)==="choice"?<div className="weekly-choices">{(target.choices||q.choices).map(x=><button key={x} className={value===x?"selected":""} onClick={()=>setValue(x)}>{x}</button>)}</div>:<input autoFocus inputMode="decimal" value={value} onChange={e=>setValue(e.target.value)} placeholder="Skriv ditt svar"/>}<Button className="primary weekly-check" disabled={!value||Boolean(feedback)} onClick={submit}>Kontrollera <Check/></Button>{feedback&&<div className={`weekly-feedback ${feedback.ok?"right":"think"}`}><h2>{feedback.ok?"✅ Bra arbetat!":feedback.showCheck?"📘 Genomgång":"💡 Tänk en gång till"}</h2><p>{feedback.text}</p><Button className="primary" onClick={proceed}>{feedback.retry?"Försök igen":feedback.showCheck?"Gör kontrolluppgiften":"Fortsätt"}<ChevronRight/></Button></div>}</article></div></main>}
const WEEKLY_CSS=`
.weekly-active{display:flex;align-items:center;justify-content:space-between;gap:18px;background:linear-gradient(135deg,#b45309,#ea580c);color:white;padding:24px;border-radius:28px;margin-bottom:17px}.weekly-active small{font-weight:950;opacity:.75}.weekly-active h2{font-size:31px;margin:4px 0}.weekly-active span{font-weight:850}.weekly-game{max-width:1180px}.weekly-workspace{display:grid;grid-template-columns:minmax(0,1fr) minmax(340px,.82fr);gap:18px;align-items:start}.weekly-workspace>section{background:#f1f5f9;border-radius:25px;padding:12px}.weekly-workspace>section h2{margin:3px 0 8px}.weekly-canvas-note{margin:8px 4px 2px;color:#64748b;font-size:14px}.weekly-game-top{display:flex;justify-content:space-between;gap:10px;font-weight:900;margin:13px 0}.weekly-question{background:white;border-radius:30px;padding:28px;box-shadow:0 15px 40px #b4530920}.weekly-question>small{font-weight:950;color:#c2410c;letter-spacing:.1em}.weekly-question>h1{font-size:clamp(25px,4vw,39px);line-height:1.25}.weekly-question>input{width:100%;height:65px;border:3px solid #fed7aa;border-radius:18px;padding:0 18px;font-size:27px;font-weight:900}.weekly-choices{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.weekly-choices button{border:3px solid transparent;background:#fff7ed;border-radius:18px;padding:18px;font-size:24px;font-weight:950}.weekly-choices button.selected{border-color:#ea580c}.weekly-check{margin-top:15px}.weekly-feedback{margin-top:15px;padding:17px;border-radius:20px}.weekly-feedback.right{background:#d1fae5;color:#065f46}.weekly-feedback.think{background:#fef3c7;color:#78350f}.confidence-card{max-width:630px;margin:15vh auto;background:white;border-radius:30px;padding:30px;text-align:center}.confidence-card>div{display:grid;gap:10px}.confidence-card button{border:3px solid #ddd6fe;background:#f5f3ff;border-radius:18px;padding:17px;font-weight:900}.weekly-result{max-width:850px}.weekly-result-card{background:white;border-radius:32px;padding:28px;text-align:center}.weekly-result-card>span{font-size:70px}.weekly-result-card>small{display:block;font-weight:950;color:#c2410c}.weekly-result-card section{text-align:left;background:#fff7ed;border-radius:19px;padding:13px 17px;margin:10px 0}.weekly-result-card section h2{margin:2px 0}.confidence-summary{background:#ede9fe;padding:13px;border-radius:16px;margin:13px 0}.mission-row>div{display:grid}.mission-row .btn{margin-left:auto}@media(max-width:850px){.weekly-workspace{grid-template-columns:1fr}}@media(max-width:700px){.weekly-active{align-items:flex-start;flex-direction:column}.weekly-choices{grid-template-columns:1fr}.weekly-question{padding:19px}}
`;

function MapScreen({profile,open,openPuzzles,back}){return <main><Button onClick={back}><ArrowLeft/>Startsidan</Button><div className="adventure-head"><span>🏰</span><div><small>ÄVENTYR</small><h1>Matematikvärldarna</h1><p>Välj ett område och fortsätt din träning.</p></div></div><div className="worlds">{WORLDS.map(w=>{let r=profile.stats.worldResults?.[w.id];return <button className={`world w${w.id}`} key={w.id} onClick={()=>open(w.id)}><b>{w.icon} {w.title}</b><small>{w.sub}</small>{r?<span>Senast {r.latestCorrect}/12 · Bäst {r.bestCorrect}/12</span>:<span>Inget resultat ännu</span>}</button>})}<button className="world future-world" disabled><b>🍰 Bråkriket</b><small>Bråk och tallinje</small><span>Kommer snart</span></button><button className="world puzzle-world" onClick={openPuzzles}><b>🧩 Gåtornas dal</b><small>Problemlösning och resonemang</small><span>Tre spår · personligt stöd</span></button><button className="world future-world" disabled><b>💰 Handelsstaden</b><small>Procent och proportionalitet</small><span>Kommer snart</span></button><button className="world future-world" disabled><b>📐 Formernas rike</b><small>Geometri</small><span>Kommer snart</span></button></div></main>}

const PUZZLE_TRACKS={support:{name:"Träna",icon:"🌱",description:"Tydliga problem, ett steg och stöd för att välja räknesätt."},base:{name:"Utmaning",icon:"🌿",description:"Flerstegsproblem, relevant information och metodval."},expert:{name:"Expert",icon:"🔥",description:"Öppna, logiska och generaliserande mästarproblem."}};
